// Monta SQL do claim. Normal: donos com flag, 21h local, nao enviado hoje (marca enviado).
// Teste/manual: body {force: 'numero'} ignora hora e NAO marca enviado.
const body = (items[0].json.body || items[0].json) || {};
const force = String(body.force || '').replace(/[^0-9]/g, '');

const dados = `SELECT u.numero, u.nome, u.timezone, u.moeda,
  to_char((NOW() AT TIME ZONE u.timezone)::date, 'DD/MM') AS data_local,
  (SELECT COALESCE(json_agg(json_build_object('categoria', COALESCE(g.categoria,'outros'), 'sub', COALESCE(g.subcategoria,''), 'descricao', g.descricao, 'valor', g.valor)), '[]'::json)
    FROM giulia_gastos g WHERE g.dono_numero = u.numero AND g.data_gasto = (NOW() AT TIME ZONE u.timezone)::date) AS gastos_hoje,
  (SELECT COALESCE(json_agg(t.titulo), '[]'::json) FROM giulia_tarefas t
    WHERE t.dono_numero = u.numero AND t.status = 'feita' AND t.feita_em >= NOW() - INTERVAL '24 hours') AS tarefas_feitas,
  (SELECT COALESCE(json_agg(json_build_object('id', t.id, 'titulo', t.titulo, 'atrasada', (t.prazo IS NOT NULL AND t.prazo < (NOW() AT TIME ZONE u.timezone)::date)) ORDER BY (t.prazo IS NULL), t.prazo ASC, t.criada_em ASC, t.id ASC), '[]'::json)
    FROM giulia_tarefas t WHERE t.dono_numero = u.numero AND t.status = 'pendente') AS tarefas_pendentes,
  (SELECT COALESCE(json_agg(json_build_object('descricao', c.descricao, 'valor', c.valor, 'atrasada', (c.vencimento < (NOW() AT TIME ZONE u.timezone)::date)) ORDER BY c.vencimento), '[]'::json)
    FROM giulia_contas_pagar c WHERE c.dono_numero = u.numero AND c.status = 'pendente' AND c.vencimento <= (NOW() AT TIME ZONE u.timezone)::date + 1) AS contas_ate_amanha,
  (SELECT COALESCE(json_agg(json_build_object('descricao', c.descricao, 'valor', c.valor)), '[]'::json)
    FROM giulia_contas_pagar c WHERE c.dono_numero = u.numero AND c.status = 'paga' AND c.pago_em >= NOW() - INTERVAL '24 hours') AS contas_pagas,
  (SELECT COALESCE(json_agg(json_build_object('hora', to_char(l.disparar_em, 'HH24:MI'), 'descricao', l.descricao, 'rec', COALESCE(l.recorrencia,'')) ORDER BY l.disparar_em), '[]'::json)
    FROM giulia_lembretes l WHERE l.dono_numero = u.numero AND l.status = 'pendente' AND l.disparar_em::date = (NOW() AT TIME ZONE u.timezone)::date + 1) AS lembretes_amanha,
  (SELECT COALESCE(json_agg(r.tarefa ORDER BY r.id), '[]'::json)
    FROM giulia_rotina r WHERE r.ativa AND r.dono_numero = u.numero AND r.dia_semana = EXTRACT(DOW FROM (NOW() AT TIME ZONE u.timezone)::date + 1)::INT) AS rotina_amanha,
  (SELECT COUNT(*) FROM giulia_envios_pendentes e WHERE e.dono_numero = u.numero AND e.status = 'aguardando_confirmacao' AND e.expira_em > NOW()) AS envios_aguardando`;

let sql;
if (force) {
  sql = `${dados}\nFROM giulia_donos u WHERE u.numero = '${force}';`;
} else {
  sql = `WITH alvo AS (\n  SELECT numero FROM giulia_donos d\n  WHERE relatorio_diario\n    AND COALESCE(d.status, 'ativo') = 'ativo'\n    AND (d.numero = '5511910441709' OR EXISTS (SELECT 1 FROM giulia_memoria m WHERE m.from_numero = d.numero AND m.role = 'user' AND m.created_at > NOW() - INTERVAL '5 days'))\n    AND to_char(NOW() AT TIME ZONE timezone, 'HH24')::int = 21\n    AND (ultimo_relatorio_diario IS NULL OR ultimo_relatorio_diario < (NOW() AT TIME ZONE timezone)::date)\n  FOR UPDATE SKIP LOCKED\n), upd AS (\n  UPDATE giulia_donos d SET ultimo_relatorio_diario = (NOW() AT TIME ZONE d.timezone)::date\n  FROM alvo WHERE d.numero = alvo.numero\n  RETURNING d.numero, d.nome, d.timezone, d.moeda\n)\n${dados.replace('FROM giulia_donos u', '').trim()}\nFROM upd u;`;
}
return [{ json: { sql } }];

// Fechamento do dia - UMA mensagem POR DONO + grafico dark premium dos gastos
const out = [];
for (const item of items) {
  const d = item.json || {};
  if (!d.numero) continue;
  function parse(v){ if (typeof v === 'string') { try { return JSON.parse(v); } catch(e) { return []; } } return v || []; }
  const gastos = parse(d.gastos_hoje);
  const feitas = parse(d.tarefas_feitas);
  const pendentes = parse(d.tarefas_pendentes);
  const contas = parse(d.contas_ate_amanha);
  const pagas = parse(d.contas_pagas);
  const lembretes = parse(d.lembretes_amanha);
  const rotina = parse(d.rotina_amanha);
  const envios = Number(d.envios_aguardando || 0);
  const SYM = d.moeda === 'USD' ? '$' : 'R$';
  const fmt = v => SYM + ' ' + (Number(v)||0).toFixed(2).replace('.', ',').replace(/\B(?=(\d{3})+(?!\d))/g, '.');

  const totalDia = gastos.reduce((s,g) => s + (Number(g.valor)||0), 0);
  const porCat = {};
  for (const g of gastos) porCat[g.categoria] = (porCat[g.categoria]||0) + (Number(g.valor)||0);
  const cats = Object.entries(porCat).sort((a,b) => b[1]-a[1]);

  let secoes = [];
  if (gastos.length) {
    const linhas = cats.slice(0,5).map(([c,v]) => `  ${c}: ${fmt(v)}`).join('\n');
    secoes.push(`*Gastos de hoje: ${fmt(totalDia)}* (${gastos.length === 1 ? '1 lancamento' : gastos.length + ' lancamentos'})\n${linhas}`);
  } else {
    secoes.push('*Gastos de hoje:* nenhum registrado - dia de cofre fechado.');
  }
  let feitoTxt = [];
  if (feitas.length) feitoTxt.push(`${feitas.length === 1 ? '1 tarefa concluida' : feitas.length + ' tarefas concluidas'} (${feitas.slice(0,3).join('; ')}${feitas.length > 3 ? '...' : ''})`);
  if (pagas.length) feitoTxt.push(`${pagas.length === 1 ? '1 conta paga' : pagas.length + ' contas pagas'} (${pagas.map(c => c.descricao).slice(0,3).join('; ')})`);
  if (feitoTxt.length) secoes.push('*Feito hoje:*\n  ' + feitoTxt.join('\n  '));

  let pend = [];
  const pendNum = pendentes.map((t, i) => ({ ...t, pos: i + 1 }));   // posicao = mesma da lista "minhas tarefas"
  const atrasadas = pendNum.filter(t => t.atrasada);
  const abertas = pendNum.filter(t => !t.atrasada);
  if (atrasadas.length) pend.push(`${atrasadas.length} tarefa${atrasadas.length>1?'s':''} atrasada${atrasadas.length>1?'s':''}: ` + atrasadas.map(t => `${t.pos}. ${t.titulo}`).slice(0,4).join('; ') + (atrasadas.length > 4 ? ` ...e mais ${atrasadas.length-4}` : ''));
  if (abertas.length) pend.push(`${abertas.length} tarefa${abertas.length>1?'s':''} em aberto: ` + abertas.map(t => `${t.pos}. ${t.titulo}`).slice(0,4).join('; ') + (abertas.length > 4 ? ` ...e mais ${abertas.length-4}` : ''));
  const contasAtras = contas.filter(c => c.atrasada);
  const contasAmanha = contas.filter(c => !c.atrasada);
  if (contasAtras.length) pend.push('conta ATRASADA: ' + contasAtras.map(c => `${c.descricao}${c.valor ? ' ' + fmt(c.valor) : ''}`).join('; '));
  if (contasAmanha.length) pend.push('vence ate amanha: ' + contasAmanha.map(c => `${c.descricao}${c.valor ? ' ' + fmt(c.valor) : ''}`).join('; '));
  if (envios > 0) pend.push(`${envios} recado${envios>1?'s':''} aguardando teu OK`);
  secoes.push(pend.length ? '*Fica pra amanha:*\n  ' + pend.join('\n  ') : '*Pendencias:* nenhuma - dia fechado sem pontas soltas.');

  let amanha = [];
  if (lembretes.length) amanha.push(lembretes.map(l => `${l.hora} ${l.descricao}${l.rec ? ' (fixo)' : ''}`).slice(0,5).join('; '));
  if (rotina.length) amanha.push('rotina: ' + rotina.join(', '));
  if (amanha.length) secoes.push('*Amanha ja agendado:*\n  ' + amanha.join('\n  '));

  // dia sem nada (sem gasto, sem feito, sem pendencia, sem agenda): nao manda "nenhum/nenhuma" - silencio.
  if (!gastos.length && !feitoTxt.length && !pend.length && !amanha.length) continue;
  const texto = `*Fechamento do dia - ${d.data_local}*\n\n` + secoes.join('\n\n');

  // grafico dark premium do dia (so se teve gasto)
  let chartUrl = '';
  if (cats.length) {
    const CORES = ['#3987e5','#199e70','#c98500','#008300','#9085e9','#e66767','#d55181','#d95926'];
    const labels = JSON.stringify(cats.slice(0,8).map(([c,v]) => c + ' - ' + fmt(v)));
    const vals = JSON.stringify(cats.slice(0,8).map(([c,v]) => Math.round(v*100)/100));
    const cores = JSON.stringify(CORES.slice(0, Math.min(cats.length,8)));
    const cfg = "{type:'doughnut',data:{labels:" + labels + ",datasets:[{data:" + vals + ",backgroundColor:" + cores + ",borderColor:'#0B1A13',borderWidth:3}]},options:{cutoutPercentage:58,layout:{padding:10},title:{display:true,text:'Gastos do dia - " + d.data_local + "',fontSize:19,fontColor:'#F5F0E8',fontFamily:'Georgia, serif',padding:12},legend:{position:'right',labels:{fontSize:12,fontColor:'#F5F0E8',padding:10,boxWidth:13}},plugins:{datalabels:{display:function(ctx){var dd=ctx.dataset.data;var t=dd.reduce(function(a,b){return a+b},0);return dd[ctx.dataIndex]/t>=0.08;},formatter:function(v,ctx){var t=ctx.dataset.data.reduce(function(a,b){return a+b},0);return Math.round(v/t*100)+'%';},color:'#ffffff',font:{weight:'bold',size:14}},doughnutlabel:{labels:[{text:'" + fmt(totalDia) + "',font:{size:20,weight:'bold'},color:'#F5F0E8'},{text:'total do dia',font:{size:11},color:'#C9A84C'}]}}}}";
    chartUrl = 'https://quickchart.io/chart?w=700&h=400&bkg=' + encodeURIComponent('#0B1A13') + '&devicePixelRatio=2&c=' + encodeURIComponent(cfg);
  }
  out.push({ json: { send_to: d.numero, send_text: texto, chart_url: chartUrl } });
}
return out;
